//! Guitar chord fingerings: the song's own `{define}` voicings and a built-in
//! table from tombatossals/chords-db (MIT), first position of each chord.
//! Ported from chordpro-tui/internal/chords/db.go with its tests; the table
//! is generated by `scripts/chords-from-json.py`.

use std::{collections::HashMap, sync::OnceLock};

/// One playable fingering, string 0 the low E. A fret of -1 is muted, 0 open,
/// and n the n-th fret counted from `base_fret` (absolute when it is 1).
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct Shape {
    pub frets: Vec<i8>,
    /// The fretting finger per string, 0 for none.
    pub fingers: Vec<u8>,
    /// The fret number of the diagram's top row (1 = at the nut).
    pub base_fret: u8,
    /// Fret rows held by one finger across strings.
    pub barres: Vec<u8>,
}

impl Shape {
    /// A barre wherever one finger frets two or more strings at one fret,
    /// for `{define}` shapes, which state fingers but not barres.
    fn infer_barres(mut self) -> Self {
        if self.barres.is_empty() {
            for finger in 1..=4u8 {
                let frets: Vec<i8> = self
                    .fingers
                    .iter()
                    .zip(&self.frets)
                    .filter(|&(&f, &fret)| f == finger && fret > 0)
                    .map(|(_, &fret)| fret)
                    .collect();
                if frets.len() >= 2 && frets.iter().all(|&f| f == frets[0]) {
                    self.barres.push(frets[0] as u8);
                }
            }
        }
        self
    }
}

/// Parses a `{define}` body: `Am base-fret 1 frets x 0 2 2 1 0 fingers 0 0 2
/// 3 1 0`. `base-fret` (or `base_fret`) defaults to 1; `x` or `N` mutes a
/// string. Returns the chord name and its shape, or `None` without frets.
/// chordpro-tui's `parseDefine` skipped fingers; ChordPro 6 states them.
pub fn parse_define(value: &str) -> Option<(String, Shape)> {
    let mut fields = value.split_whitespace().peekable();
    let name = fields.next()?.to_owned();
    let mut shape = Shape {
        frets: Vec::new(),
        fingers: Vec::new(),
        base_fret: 1,
        barres: Vec::new(),
    };
    while let Some(field) = fields.next() {
        match field.to_ascii_lowercase().as_str() {
            "base-fret" | "base_fret" | "basefret" => {
                if let Some(n) = fields.next().and_then(|f| f.parse().ok()) {
                    shape.base_fret = n;
                }
            }
            "frets" => {
                while let Some(&token) = fields.peek() {
                    if token.eq_ignore_ascii_case("fingers") || token.eq_ignore_ascii_case("keys") {
                        break;
                    }
                    shape.frets.push(token.parse().unwrap_or(-1));
                    fields.next();
                }
            }
            "fingers" => {
                while let Some(&token) = fields.peek() {
                    if token.eq_ignore_ascii_case("frets") || token.eq_ignore_ascii_case("keys") {
                        break;
                    }
                    shape.fingers.push(token.parse().unwrap_or(0));
                    fields.next();
                }
            }
            _ => {}
        }
    }
    if shape.frets.is_empty() {
        return None;
    }
    shape.fingers.resize(shape.frets.len(), 0);
    Some((name, shape.infer_barres()))
}

/// (key, suffix) → shape, loaded once.
fn table() -> &'static HashMap<(String, String), Shape> {
    static TABLE: OnceLock<HashMap<(String, String), Shape>> = OnceLock::new();
    TABLE.get_or_init(|| {
        let numbers = |field: &str| -> Vec<i32> {
            field
                .split_whitespace()
                .filter_map(|n| n.parse().ok())
                .collect()
        };
        include_str!("../data/guitar.tsv")
            .lines()
            .filter(|line| !line.starts_with('#') && !line.is_empty())
            .filter_map(|line| {
                let cols: Vec<&str> = line.split('\t').collect();
                let [key, suffix, base, frets, fingers, barres] = cols[..] else {
                    return None;
                };
                Some((
                    (key.to_owned(), suffix.to_owned()),
                    Shape {
                        frets: numbers(frets).into_iter().map(|f| f as i8).collect(),
                        fingers: numbers(fingers).into_iter().map(|f| f as u8).collect(),
                        base_fret: base.parse().ok()?,
                        barres: numbers(barres).into_iter().map(|b| b as u8).collect(),
                    },
                ))
            })
            .collect()
    })
}

/// The table's key for a pitch class: it spells Csharp and Fsharp but Eb,
/// Ab and Bb.
const KEY_FOR_PC: [&str; 12] = [
    "C", "Csharp", "D", "Eb", "E", "F", "Fsharp", "G", "Ab", "A", "Bb", "B",
];

/// ChordPro spellings the table does not list under that name.
fn alias(suffix: &str) -> Option<&'static str> {
    Some(match suffix {
        "" | "maj" | "M" => "major",
        "m" | "min" | "-" => "minor",
        "+" | "aug5" => "aug",
        "7sus" => "7sus4",
        _ => return None,
    })
}

/// The root's pitch class (0 = C) and the rest of the name.
fn split_root(name: &str) -> Option<(usize, &str)> {
    let mut chars = name.chars();
    let base: i32 = match chars.next()? {
        'C' => 0,
        'D' => 2,
        'E' => 4,
        'F' => 5,
        'G' => 7,
        'A' => 9,
        'B' => 11,
        _ => return None,
    };
    let (shift, rest) = match name[1..].chars().next() {
        Some('#') => (1, &name[2..]),
        Some('b') => (-1, &name[2..]),
        _ => (0, &name[1..]),
    };
    Some((((base + shift) % 12 + 12) as usize % 12, rest))
}

/// The easiest built-in fingering for a chord name, if it is a chord the
/// table knows: the suffix as written, then its alias, then for a slash chord
/// whose bass is not catalogued, the chord without its bass.
pub fn lookup(name: &str) -> Option<Shape> {
    let (pc, rest) = split_root(name.trim())?;
    let key = KEY_FOR_PC[pc];
    let mut candidates = vec![rest];
    candidates.extend(alias(rest));
    if let Some((base, _)) = rest.split_once('/') {
        candidates.push(base);
        candidates.extend(alias(base));
    }
    candidates
        .into_iter()
        .find_map(|suffix| table().get(&(key.to_owned(), suffix.to_owned())).cloned())
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn lookup_common_chords() {
        for (name, frets, base) in [
            ("C", vec![-1, 3, 2, 0, 1, 0], 1),
            ("Am", vec![-1, 0, 2, 2, 1, 0], 1),
            ("G", vec![3, 2, 0, 0, 0, 3], 1),
        ] {
            let shape = lookup(name).unwrap_or_else(|| panic!("{name} not found"));
            assert_eq!(shape.frets, frets, "{name}");
            assert_eq!(shape.base_fret, base, "{name}");
        }
    }

    #[test]
    fn lookup_resolves_realistic_names() {
        for name in [
            "Cmaj7", "Dm7", "G7", "C#m", "Bb", "Ab", "G/B", "Csus4", "Aadd9", "F#m7b5", "Em7",
            "D/F#", "Bbm", "F#", "Gsus2",
        ] {
            assert!(lookup(name).is_some(), "{name}");
        }
    }

    #[test]
    fn lookup_rejects_non_chords() {
        for name in ["", "N.C.", "%", "x"] {
            assert!(lookup(name).is_none(), "{name}");
        }
    }

    #[test]
    fn slash_falls_back_to_base() {
        assert_eq!(lookup("Cmaj7/G"), lookup("Cmaj7"));
        assert!(lookup("Cmaj7").is_some());
    }

    #[test]
    fn the_table_holds_every_generated_row() {
        assert_eq!(table().len(), 828);
    }

    #[test]
    fn define_parses_frets_fingers_and_base_fret() {
        let (name, shape) = parse_define("Am base-fret 1 frets x 0 2 2 1 0").unwrap();
        assert_eq!(name, "Am");
        assert_eq!(shape.frets, [-1, 0, 2, 2, 1, 0]);
        assert_eq!(shape.base_fret, 1);
        assert_eq!(shape.fingers, [0; 6]);
        let (_, f) = parse_define("F base_fret 1 frets 1 3 3 2 1 1 fingers 1 3 4 2 1 1").unwrap();
        assert_eq!(f.fingers, [1, 3, 4, 2, 1, 1]);
        assert_eq!(f.barres, [1], "finger 1 across fret 1 is a barre");
        let (_, high) = parse_define("Bm base-fret 7 frets x 1 3 3 2 1").unwrap();
        assert_eq!(high.base_fret, 7);
        assert!(parse_define("X").is_none());
    }
}
